// 진도백구 Base64 애니메이션 스프라이트 프레임 에셋
import AppKit
import SwiftUI

public enum JindoDogPetFrames {
    private static let base64Frames: [String] = [
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    ]

    public static let cachedImages: [NSImage] = {
        base64Frames.compactMap { b64 in
            guard let data = Data(base64Encoded: b64, options: .ignoreUnknownCharacters) else { return nil }
            return NSImage(data: data)
        }
    }()
}

public struct JindoDogPetAsset: View {
    public let isHorizontal: Bool
    public let isRightEdge: Bool
    public let accentColor: Color

    public init(isHorizontal: Bool, isRightEdge: Bool = false, accentColor: Color = .red) {
        self.isHorizontal = isHorizontal
        self.isRightEdge = isRightEdge
        self.accentColor = accentColor
    }

    public var body: some View {
        TimelineView(.periodic(from: .now, by: 0.0625)) { context in
            let count = JindoDogPetFrames.cachedImages.count
            if count > 0 {
                let frameIndex = Int(context.date.timeIntervalSince1970 * 16) % count
                if let nsImage = JindoDogPetFrames.cachedImages[safe: frameIndex] {
                    Image(nsImage: nsImage)
                        .resizable()
                        .interpolation(.high)
                        .aspectRatio(contentMode: .fit)
                        .frame(width: isHorizontal ? 35 : 40, height: isHorizontal ? 50 : 58)
                        .scaleEffect(x: isRightEdge ? -1.0 : 1.0, y: 1.0)
                }
            }
        }
    }
}
